fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    // Iterate over each parent index
    for i in 0..(n / 2) {
        let parent = a[i];
        // Check left child
        let left_child_index = 2 * i + 1;
        if left_child_index < n {
            if a[left_child_index] < parent {
                return false; // Left child is less than parent
            }
        }
        // Check right child
        let right_child_index = 2 * i + 2;
        if right_child_index < n {
            if a[right_child_index] < parent {
                return false; // Right child is less than parent
            }
        }
    }
    true // All parent-child comparisons satisfied the min-heap property
}